type definitionWhere[Q psql.Filterable] struct {
	cols      definitionColumns
	ID        psql.WhereMod[Q, int64]
	Kind      psql.WhereMod[Q, enums.DefinitionKind]
	Key       psql.WhereMod[Q, string]
	Name      psql.WhereNullMod[Q, string]
	GroupKey  psql.WhereNullMod[Q, string]
	CreatedAt psql.WhereMod[Q, time.Time]
	UpdatedAt psql.WhereMod[Q, time.Time]
	R         definitionWhereR[Q]
}

func (definitionWhere[Q]) AliasedAs(alias string) definitionWhere[Q] {
	return buildDefinitionWhere[Q](buildDefinitionColumns(alias))
}

func buildDefinitionWhere[Q psql.Filterable](cols definitionColumns) definitionWhere[Q] {
	return definitionWhere[Q]{
		cols:      cols,
		ID:        psql.Where[Q, int64](cols.ID.Expression),
		Kind:      psql.Where[Q, enums.DefinitionKind](cols.Kind.Expression),
		Key:       psql.Where[Q, string](cols.Key.Expression),
		Name:      psql.WhereNull[Q, string](cols.Name.Expression),
		GroupKey:  psql.WhereNull[Q, string](cols.GroupKey.Expression),
		CreatedAt: psql.Where[Q, time.Time](cols.CreatedAt.Expression),
		UpdatedAt: psql.Where[Q, time.Time](cols.UpdatedAt.Expression),
		R:         definitionWhereR[Q]{cols: cols},
	}
}

// definitionWhereR holds the relationship-based filters of
// definitionWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type definitionWhereR[Q psql.Filterable] struct {
	cols definitionColumns
}

// HasDefinitionVersions filters parents that have a matching DefinitionVersions using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to DefinitionVersions).
func (w definitionWhereR[Q]) HasDefinitionVersions(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(DefinitionVersions.NameExpr()),
		sm.Where(DefinitionVersions.Columns.DefinitionID.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

