// NULL-tolerant scan buffer for definitionScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type definitionPreloadBuf struct {
	ID        null.Val[int64]
	Kind      null.Val[enums.DefinitionKind]
	Key       null.Val[string]
	Name      null.Val[string]
	GroupKey  null.Val[string]
	CreatedAt null.Val[time.Time]
	UpdatedAt null.Val[time.Time]
}

// definitionScanMapperNullable maps the preloaded definition
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func definitionScanMapperNullable(prefix string) scan.Mapper[*Definition] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*Definition, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *definitionPreloadBuf) any
		}
		targets := make([]target, 0, 7)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *definitionPreloadBuf) any { return &b.ID }})
			case "kind":
				targets = append(targets, target{i, func(b *definitionPreloadBuf) any { return &b.Kind }})
			case "key":
				targets = append(targets, target{i, func(b *definitionPreloadBuf) any { return &b.Key }})
			case "name":
				targets = append(targets, target{i, func(b *definitionPreloadBuf) any { return &b.Name }})
			case "group_key":
				targets = append(targets, target{i, func(b *definitionPreloadBuf) any { return &b.GroupKey }})
			case "created_at":
				targets = append(targets, target{i, func(b *definitionPreloadBuf) any { return &b.CreatedAt }})
			case "updated_at":
				targets = append(targets, target{i, func(b *definitionPreloadBuf) any { return &b.UpdatedAt }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(definitionPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*Definition, error) {
				buf := link.(*definitionPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.IsValue()) &&
					!(buf.Kind.IsValue()) &&
					!(buf.Key.IsValue()) &&
					!(buf.Name.IsValue()) &&
					!(buf.GroupKey.IsValue()) &&
					!(buf.CreatedAt.IsValue()) &&
					!(buf.UpdatedAt.IsValue()) {
					return nil, nil
				}

				o := new(Definition)
				if buf.ID.IsValue() {
					o.ID = buf.ID.MustGet()
				}
				if buf.Kind.IsValue() {
					o.Kind = buf.Kind.MustGet()
				}
				if buf.Key.IsValue() {
					o.Key = buf.Key.MustGet()
				}
				o.Name = buf.Name
				o.GroupKey = buf.GroupKey
				if buf.CreatedAt.IsValue() {
					o.CreatedAt = buf.CreatedAt.MustGet()
				}
				if buf.UpdatedAt.IsValue() {
					o.UpdatedAt = buf.UpdatedAt.MustGet()
				}
				return o, nil
			}
	}
}

func (o *Definition) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "DefinitionVersions":
		rels, ok := retrieved.(DefinitionVersionSlice)
		if !ok {
			return fmt.Errorf("definition cannot load %T as %q", retrieved, name)
		}

		o.R.DefinitionVersions = rels
		o.R.Loaded.DefinitionVersions = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Definition = o
				rel.R.Loaded.Definition = true
			}
		}
		return nil
	case "PlayerGameStats":
		rels, ok := retrieved.(PlayerGameStatSlice)
		if !ok {
			return fmt.Errorf("definition cannot load %T as %q", retrieved, name)
		}

		o.R.PlayerGameStats = rels
		o.R.Loaded.PlayerGameStats = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Definition = o
				rel.R.Loaded.Definition = true
			}
		}
		return nil
	case "PlayerMinigameStats":
		rels, ok := retrieved.(PlayerMinigameStatSlice)
		if !ok {
			return fmt.Errorf("definition cannot load %T as %q", retrieved, name)
		}

		o.R.PlayerMinigameStats = rels
		o.R.Loaded.PlayerMinigameStats = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Definition = o
				rel.R.Loaded.Definition = true
			}
		}
		return nil
	case "Stats":
		rels, ok := retrieved.(StatSlice)
		if !ok {
			return fmt.Errorf("definition cannot load %T as %q", retrieved, name)
		}

		o.R.Stats = rels
		o.R.Loaded.Stats = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Definition = o
				rel.R.Loaded.Definition = true
			}
		}
		return nil
	default:
		return fmt.Errorf("definition has no relationship %q", name)
	}
}

type definitionPreloader struct{}

func buildDefinitionPreloader() definitionPreloader {
	return definitionPreloader{}
}

type definitionThenLoader[Q orm.Loadable] struct {
	DefinitionVersions  func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	PlayerGameStats     func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	PlayerMinigameStats func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Stats               func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildDefinitionThenLoader[Q orm.Loadable]() definitionThenLoader[Q] {
	type DefinitionVersionsLoadInterface interface {
		LoadDefinitionVersions(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type PlayerGameStatsLoadInterface interface {
		LoadPlayerGameStats(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type PlayerMinigameStatsLoadInterface interface {
		LoadPlayerMinigameStats(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type StatsLoadInterface interface {
		LoadStats(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return definitionThenLoader[Q]{
		DefinitionVersions: thenLoadBuilder[Q](
			"DefinitionVersions",
			func(ctx context.Context, exec bob.Executor, retrieved DefinitionVersionsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadDefinitionVersions(ctx, exec, mods...)
			},
		),
		PlayerGameStats: thenLoadBuilder[Q](
			"PlayerGameStats",
			func(ctx context.Context, exec bob.Executor, retrieved PlayerGameStatsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadPlayerGameStats(ctx, exec, mods...)
			},
		),
		PlayerMinigameStats: thenLoadBuilder[Q](
			"PlayerMinigameStats",
			func(ctx context.Context, exec bob.Executor, retrieved PlayerMinigameStatsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadPlayerMinigameStats(ctx, exec, mods...)
			},
		),
		Stats: thenLoadBuilder[Q](
			"Stats",
			func(ctx context.Context, exec bob.Executor, retrieved StatsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadStats(ctx, exec, mods...)
			},
		),
	}
}

// LoadDefinitionVersions loads the definition's DefinitionVersions into the .R struct
func (o *Definition) LoadDefinitionVersions(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.DefinitionVersions = nil
	o.R.Loaded.DefinitionVersions = false

	related, err := o.DefinitionVersions(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.Definition = o
		rel.R.Loaded.Definition = true
	}

	o.R.DefinitionVersions = related
	o.R.Loaded.DefinitionVersions = true
	return nil
}

// LoadDefinitionVersions loads the definition's DefinitionVersions into the .R struct
func (os DefinitionSlice) LoadDefinitionVersions(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	definitionVersions, err := os.DefinitionVersions(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.DefinitionVersions = nil
		o.R.Loaded.DefinitionVersions = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	definitionByKey := make(map[int64][]*Definition, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		definitionByKey[o.ID] = append(definitionByKey[o.ID], o)
	}

	for _, rel := range definitionVersions {

		owners, ok := definitionByKey[rel.DefinitionID]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.Definition = o
			rel.R.Loaded.Definition = true

			o.R.DefinitionVersions = append(o.R.DefinitionVersions, rel)

		}
	}

	return nil
}

