// definitionC is where relationship counts are stored.
type definitionC struct {
	DefinitionVersions  *int64
	PlayerGameStats     *int64
	PlayerMinigameStats *int64
	Stats               *int64
}

// PreloadCount sets a count in the C struct by name
func (o *Definition) PreloadCount(name string, count int64) error {
	if o == nil {
		return nil
	}

	switch name {
	case "DefinitionVersions":
		o.C.DefinitionVersions = &count
	case "PlayerGameStats":
		o.C.PlayerGameStats = &count
	case "PlayerMinigameStats":
		o.C.PlayerMinigameStats = &count
	case "Stats":
		o.C.Stats = &count
	}
	return nil
}

type definitionCountPreloader struct {
	DefinitionVersions  func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
	PlayerGameStats     func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
	PlayerMinigameStats func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
	Stats               func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
}

func buildDefinitionCountPreloader() definitionCountPreloader {
	return definitionCountPreloader{
		DefinitionVersions: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*Definition]("DefinitionVersions", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = Definitions.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(DefinitionVersions.NameAsExpr()),
					sm.Where(psql.Quote(DefinitionVersions.Alias(), "definition_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
		PlayerGameStats: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*Definition]("PlayerGameStats", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = Definitions.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(PlayerGameStats.NameAsExpr()),
					sm.Where(psql.Quote(PlayerGameStats.Alias(), "definition_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
		PlayerMinigameStats: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*Definition]("PlayerMinigameStats", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = Definitions.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(PlayerMinigameStats.NameAsExpr()),
					sm.Where(psql.Quote(PlayerMinigameStats.Alias(), "definition_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
		Stats: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*Definition]("Stats", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = Definitions.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(Stats.NameAsExpr()),
					sm.Where(psql.Quote(Stats.Alias(), "definition_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
	}
}

type definitionCountThenLoader[Q orm.Loadable] struct {
	DefinitionVersions  func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	PlayerGameStats     func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	PlayerMinigameStats func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Stats               func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildDefinitionCountThenLoader[Q orm.Loadable]() definitionCountThenLoader[Q] {
	type DefinitionVersionsCountInterface interface {
		LoadCountDefinitionVersions(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type PlayerGameStatsCountInterface interface {
		LoadCountPlayerGameStats(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type PlayerMinigameStatsCountInterface interface {
		LoadCountPlayerMinigameStats(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type StatsCountInterface interface {
		LoadCountStats(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return definitionCountThenLoader[Q]{
		DefinitionVersions: countThenLoadBuilder[Q](
			"DefinitionVersions",
			func(ctx context.Context, exec bob.Executor, retrieved DefinitionVersionsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountDefinitionVersions(ctx, exec, mods...)
			},
		),
		PlayerGameStats: countThenLoadBuilder[Q](
			"PlayerGameStats",
			func(ctx context.Context, exec bob.Executor, retrieved PlayerGameStatsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountPlayerGameStats(ctx, exec, mods...)
			},
		),
		PlayerMinigameStats: countThenLoadBuilder[Q](
			"PlayerMinigameStats",
			func(ctx context.Context, exec bob.Executor, retrieved PlayerMinigameStatsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountPlayerMinigameStats(ctx, exec, mods...)
			},
		),
		Stats: countThenLoadBuilder[Q](
			"Stats",
			func(ctx context.Context, exec bob.Executor, retrieved StatsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountStats(ctx, exec, mods...)
			},
		),
	}
}

