type definitionJoins[Q dialect.Joinable] struct {
	typ                 string
	DefinitionVersions  modAs[Q, definitionVersionColumns]
	PlayerGameStats     modAs[Q, playerGameStatColumns]
	PlayerMinigameStats modAs[Q, playerMinigameStatColumns]
	Stats               modAs[Q, statColumns]
}

func (j definitionJoins[Q]) aliasedAs(alias string) definitionJoins[Q] {
	return buildDefinitionJoins[Q](buildDefinitionColumns(alias), j.typ)
}

func buildDefinitionJoins[Q dialect.Joinable](cols definitionColumns, typ string) definitionJoins[Q] {
	return definitionJoins[Q]{
		typ: typ,
		DefinitionVersions: modAs[Q, definitionVersionColumns]{
			c: DefinitionVersions.Columns,
			f: func(to definitionVersionColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, DefinitionVersions.NameExpr().As(to.Alias())).On(
						to.DefinitionID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		PlayerGameStats: modAs[Q, playerGameStatColumns]{
			c: PlayerGameStats.Columns,
			f: func(to playerGameStatColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, PlayerGameStats.NameExpr().As(to.Alias())).On(
						to.DefinitionID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		PlayerMinigameStats: modAs[Q, playerMinigameStatColumns]{
			c: PlayerMinigameStats.Columns,
			f: func(to playerMinigameStatColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, PlayerMinigameStats.NameExpr().As(to.Alias())).On(
						to.DefinitionID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		Stats: modAs[Q, statColumns]{
			c: Stats.Columns,
			f: func(to statColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Stats.NameExpr().As(to.Alias())).On(
						to.DefinitionID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
